"""html_viewer_template: CSS and JS for the subtitle HTML viewer.

Separated from html_viewer.py to keep the logic file concise.
"""

VIEWER_CSS = """\
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#09090b;--s1:#0f0f13;--s2:#18181c;--s3:#1c1c22;
  --b:#27272a;--bs:#1e1e24;
  --ac:#3b82f6;--ac-dim:rgba(59,130,246,.12);--ac-glow:rgba(59,130,246,.3);
  --tx:#e4e4e7;--muted:#71717a;--dim:#52525b;
  --tim:#34d399;--tim-dim:rgba(52,211,153,.1);
  --err:#f87171;--err-dim:rgba(248,113,113,.1);
}
::-webkit-scrollbar{width:3px}::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--b);border-radius:2px}
::-webkit-scrollbar-thumb:hover{background:var(--dim)}
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  background:var(--bg);color:var(--tx);height:100vh;display:flex;
  flex-direction:column;overflow:hidden;font-size:13px;line-height:1.5}

/* Header */
header{height:52px;padding:0 20px;background:var(--s1);border-bottom:1px solid var(--b);
  display:flex;align-items:center;gap:12px;flex-shrink:0;z-index:10}
.hd-logo{display:flex;align-items:center;gap:8px;color:var(--tx);flex-shrink:0}
.hd-logo svg{color:var(--ac)}
.hd-title{font-size:14px;font-weight:600;letter-spacing:-.3px}
.hd-file{font-size:12px;color:var(--muted);background:var(--s3);padding:2px 9px;
  border-radius:4px;border:1px solid var(--b);max-width:300px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hd-div{width:1px;height:20px;background:var(--b);flex-shrink:0}
.hd-right{margin-left:auto;display:flex;align-items:center;gap:8px}
.badge{font-size:11px;color:var(--muted);background:var(--s3);
  border:1px solid var(--b);padding:2px 10px;border-radius:20px}

/* Buttons */
.btn{display:inline-flex;align-items:center;gap:5px;padding:5px 12px;
  border-radius:6px;border:1px solid var(--b);cursor:pointer;
  font-size:12px;font-family:inherit;font-weight:500;
  background:var(--s2);color:var(--tx);transition:all .15s;outline:none;white-space:nowrap}
.btn:hover{background:var(--s3);border-color:var(--dim)}
.btn:active{transform:scale(.97)}
.btn svg{flex-shrink:0}
.btn-ac{background:var(--ac);border-color:var(--ac);color:#fff;
  box-shadow:0 0 14px var(--ac-glow)}
.btn-ac:hover{background:#60a5fa;border-color:#60a5fa;box-shadow:0 0 20px var(--ac-glow)}
.btn-outline{background:transparent;border-color:var(--b);color:var(--muted)}
.btn-outline:hover{background:var(--s2);color:var(--tx);border-color:var(--dim)}
.btn-x{background:transparent;border-color:transparent;color:var(--dim);
  padding:3px 5px;border-radius:4px;min-width:26px;justify-content:center}
.btn-x:hover{background:var(--err-dim);border-color:var(--err);color:var(--err)}

/* Layout */
.main{display:flex;flex:1;overflow:hidden}

/* Subtitle panel */
.sub-panel{width:55%;display:flex;flex-direction:column;
  border-right:1px solid var(--b);overflow:hidden}
.toolbar{display:flex;align-items:center;gap:6px;padding:8px 14px;
  background:var(--s1);border-bottom:1px solid var(--b);flex-shrink:0}
.toolbar-sep{flex:1}
.sub-count{font-size:11px;color:var(--dim)}
.sub-wrap{overflow-y:auto;flex:1}

/* Table */
table{width:100%;border-collapse:collapse}
thead th{position:sticky;top:0;z-index:5;background:var(--s1);
  color:var(--dim);font-weight:500;font-size:10px;letter-spacing:.8px;
  text-transform:uppercase;padding:8px 10px;text-align:left;
  border-bottom:1px solid var(--b)}
tbody tr{border-bottom:1px solid var(--bs);cursor:pointer;
  transition:background .1s}
tbody tr:hover{background:var(--s1)}
tr.active{background:var(--ac-dim)!important;box-shadow:inset 3px 0 0 var(--ac)}
tr.active .idx-n{color:var(--ac);font-weight:600}
td{padding:5px 8px;vertical-align:middle}
td.c-idx{width:40px;text-align:center}
.idx-n{display:inline-flex;align-items:center;justify-content:center;
  width:24px;height:24px;font-size:11px;color:var(--dim);border-radius:50%}
td.c-time{width:120px}
.time-wrap{background:var(--tim-dim);border:1px solid rgba(52,211,153,.18);
  border-radius:5px;padding:3px 7px}
.time-wrap input{font-family:'JetBrains Mono','Fira Code','Courier New',monospace;
  font-size:11px;color:var(--tim);background:transparent;border:none;
  outline:none;width:100%;letter-spacing:.4px}
td.c-txt textarea{width:100%;background:transparent;border:1px solid transparent;
  border-radius:5px;color:var(--tx);font-family:inherit;font-size:13px;
  line-height:1.5;padding:4px 6px;resize:vertical;min-height:38px;
  outline:none;transition:border-color .15s,background .15s}
td.c-txt textarea:focus{border-color:var(--ac);background:var(--ac-dim)}
td.c-del{width:34px;text-align:center}

/* Media panel */
.media-panel{flex:1;display:flex;flex-direction:column;background:#000}
.player-wrap{position:relative;background:#000;flex:1;display:flex;
  align-items:center;justify-content:center;overflow:hidden}
.ph{display:flex;flex-direction:column;align-items:center;gap:12px}
.ph svg{opacity:.25}
.ph p{font-size:13px;color:var(--muted)}
.ph small{font-size:11px;color:var(--dim)}
video{max-width:100%;max-height:100%;outline:none}
audio{width:calc(100% - 32px);margin:0 16px}
#sub-overlay{position:absolute;bottom:58px;left:50%;transform:translateX(-50%);
  background:rgba(0,0,0,.8);backdrop-filter:blur(10px);
  -webkit-backdrop-filter:blur(10px);color:#fff;padding:7px 18px;
  border-radius:8px;font-size:15px;font-weight:500;text-align:center;
  max-width:88%;pointer-events:none;display:none;white-space:pre-wrap;
  border:1px solid rgba(255,255,255,.08);line-height:1.6;
  text-shadow:0 1px 4px rgba(0,0,0,.9)}

/* File picker */
.file-bar{display:flex;align-items:center;gap:10px;padding:9px 16px;
  background:var(--s1);border-top:1px solid var(--b);flex-shrink:0}
.upload-btn{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;
  background:var(--s2);border:1px solid var(--b);border-radius:6px;
  cursor:pointer;font-size:12px;font-weight:500;color:var(--tx);
  transition:all .15s}
.upload-btn:hover{background:var(--s3);border-color:var(--dim)}
.upload-btn svg{color:var(--muted)}
.file-lbl{font-size:12px;color:var(--muted);flex:1;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
input[type=file]{display:none}
.kbd{font-size:10px;color:var(--dim);background:var(--s3);
  padding:1px 5px;border-radius:3px;border:1px solid var(--b);font-family:inherit}"""


def build_viewer_js(subs_json: str, export_filename: str) -> str:
    """Return the inline JavaScript block with embedded subtitle data."""
    return f"""\
const SUBS={subs_json};
let media=null,activeRow=-1;

function msToTs(ms){{
  ms=Math.max(0,Math.round(ms));
  const h=Math.floor(ms/3600000);ms%=3600000;
  const m=Math.floor(ms/60000);ms%=60000;
  const s=Math.floor(ms/1000);ms%=1000;
  return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+','+String(ms).padStart(3,'0');
}}
function tsToMs(ts){{
  const [hms,mil]=ts.replace(',','.').split('.');
  const [h,m,s]=hms.split(':').map(Number);
  return (h*3600+m*60+s)*1000+Number(mil||0);
}}
function esc(s){{return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}}

function addRow(){{
  const last=SUBS[SUBS.length-1];
  const start=last?last.end+100:0;
  SUBS.push({{index:SUBS.length+1,start,end:start+2000,text:''}});
  render();
  document.getElementById('sw').scrollTop=99999;
}}
function delRow(i){{SUBS.splice(i,1);render();}}
function updTime(i,f,v){{const ms=tsToMs(v);if(f===0)SUBS[i].start=ms;else SUBS[i].end=ms;}}
function updText(i,v){{SUBS[i].text=v;}}

function render(){{
  const tbody=document.getElementById('sb');
  tbody.innerHTML='';
  document.querySelector('.sub-count').textContent=SUBS.length+' cues';
  SUBS.forEach((s,i)=>{{
    const tr=document.createElement('tr');
    tr.dataset.i=i;tr.onclick=()=>seekTo(i);
    tr.innerHTML=
      `<td class="c-idx"><span class="idx-n">${{i+1}}</span></td>`+
      `<td class="c-time"><div class="time-wrap"><input value="${{msToTs(s.start)}}" onchange="updTime(${{i}},0,this.value)" onclick="e=>e.stopPropagation()"></div></td>`+
      `<td class="c-time"><div class="time-wrap"><input value="${{msToTs(s.end)}}" onchange="updTime(${{i}},1,this.value)" onclick="e=>e.stopPropagation()"></div></td>`+
      `<td class="c-txt"><textarea rows="2" onchange="updText(${{i}},this.value)" onclick="event.stopPropagation()">${{esc(s.text)}}</textarea></td>`+
      `<td class="c-del"><button class="btn btn-x" onclick="delRow(${{i}});event.stopPropagation()" title="Delete">✕</button></td>`;
    tbody.appendChild(tr);
  }});
}}

function loadMedia(input){{
  const file=input.files[0];if(!file)return;
  document.querySelector('.file-lbl').textContent=file.name;
  const wrap=document.getElementById('pw');
  const ph=wrap.querySelector('.ph');if(ph)ph.remove();
  if(media)media.remove();
  const isVid=file.type.startsWith('video/');
  media=document.createElement(isVid?'video':'audio');
  media.controls=true;
  media.src=URL.createObjectURL(file);
  wrap.insertBefore(media,document.getElementById('sub-overlay'));
  media.addEventListener('timeupdate',onTick);
}}

function seekTo(i){{if(!media)return;media.currentTime=SUBS[i].start/1000;media.play();}}

function onTick(){{
  const cur=media.currentTime*1000;
  const ov=document.getElementById('sub-overlay');
  let found=-1;
  for(let i=0;i<SUBS.length;i++){{if(cur>=SUBS[i].start&&cur<=SUBS[i].end){{found=i;break;}}}}
  ov.textContent=found>=0?SUBS[found].text:'';
  ov.style.display=found>=0?'block':'none';
  if(found!==activeRow){{
    document.querySelectorAll('#sb tr').forEach(r=>r.classList.remove('active'));
    if(found>=0){{
      const row=document.querySelector('#sb tr[data-i="'+found+'"]');
      if(row){{row.classList.add('active');row.scrollIntoView({{block:'nearest',behavior:'smooth'}});}}
    }}
    activeRow=found;
  }}
}}

function exportSRT(){{
  const lines=SUBS.map((s,i)=>i+1+'\\n'+msToTs(s.start)+' --> '+msToTs(s.end)+'\\n'+s.text);
  const blob=new Blob([lines.join('\\n\\n')],{{type:'text/plain'}});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);
  a.download='{export_filename}';a.click();
}}

document.addEventListener('keydown',e=>{{
  if((e.ctrlKey||e.metaKey)&&e.key==='s'){{e.preventDefault();exportSRT();}}
}});

render();"""
